raw = open(sys.argv[1], encoding='utf-8').read()
m = re.search(r'<script type="application/json" data-target="react-app.embeddedData">(.*?)</script>', raw, re.S)
if not m:
 print("no embedded data"); sys.exit(1)
data = json.loads(m.group(1))

def walk(o):
 if isinstance(o, dict):
 if o.get('__typename') == 'Issue' and o.get('body'):
 yield o
 for v in o.values():
 yield from walk(v)
 elif isinstance(o, list):
 for v in o:
 yield from walk(v)

for iss in walk(data):
 title = iss.get('title'); body = iss.get('body')
 if title and body:
 text = html.unescape(re.sub(r'<[^>]+>', '', body))
 text = re.sub(r'\n{3,}', '\n\n', text).strip()
 print("TITLE:", title)
 print("=====BODY=====")
 print(text)
 break
else:
